SELECT id, order_id, unit_price, LAG(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id) AS prev_quantity, LEAD(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id) AS next_quantity, LAG(unit_price) OVER (PARTITION BY order_id ORDER BY quantity, id) AS prev_unit_price, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY quantity, id) AS event_seq, LAST_VALUE(unit_price, TRUE) OVER (ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_unit_price FROM order_items
